topics:[
{lvl:"A1",t:"Pronouns and “to be”",n:"Persian drops the subject pronoun freely. “To be” is either the full verb هستم، هستی، است، هستیم، هستید، هستند or a short ending: ‑am, ‑i, ‑ast (spoken ‑e), ‑im, ‑id, ‑and. Negative: نیستم، نیستی، نیست…",d:[["I am a student","من دانشجو هستم/دانشجو هستم/دانشجوام/من دانشجوام"],["you are tired","تو خسته ای/خسته ای/تو خسته هستی"],["they are not here","آنها اینجا نیستند/اونا اینجا نیستن/اینجا نیستند"]]},
{lvl:"A1",t:"Plurals",n:"‑hā works for almost everything and is standard in speech. ‑ān is more formal and used mainly for people and some animate nouns.",d:[["the books","کتاب ها"],["the children","بچه ها"],["women (formal)","زنان"]]},
{lvl:"A1",t:"Ezafe",n:"An unwritten ‑e links a noun to its adjective or possessor: ketāb‑e bozorg. After a vowel it becomes ‑ye, written ی after ا or و, and often ی or ٔ after silent ه.",d:[["the red car","ماشین قرمز"],["Ali's house","خانه علی/خانه ی علی/خونه علی"],["the big city","شهر بزرگ"]]},
{lvl:"A1",t:"Possessive endings",n:"Attach ‑am, ‑at, ‑ash, ‑emān, ‑etān, ‑eshān directly to the noun: ketābam “my book”. Spoken: ‑emun, ‑etun, ‑eshun.",d:[["my name","اسمم"],["his book","کتابش"],["our house","خانه مان/خونمون/خانه ما"]]},
{lvl:"A1",t:"Present tense",n:"mi‑ + present stem + personal ending (‑am, ‑i, ‑ad, ‑im, ‑id, ‑and). Present stems are irregular and must be learned: raftan → rav, khordan → khor, khāndan → khān.",d:[["I go","می روم/میرم/من می روم"],["she eats","می خورد/میخوره/او می خورد"],["we read","می خوانیم/میخونیم/ما می خوانیم"]]},
{lvl:"A1",t:"Negation",n:"Prefix na‑ (ne‑ before mi‑): nemiravam “I don't go”. “Not to be” is nist. “To have” takes no mi‑: dāram → nadāram.",d:[["I don't go","نمی روم/نمیرم"],["it is not","نیست"],["I don't have","ندارم"]]},
{lvl:"A1",t:"Object marker rā",n:"A definite direct object takes را (spoken ‑o / ‑ro). Indefinite objects don't.",d:[["I see the book","کتاب را می بینم/کتابو میبینم"],["I love her","او را دوست دارم/دوستش دارم"],["I bought a car","یک ماشین خریدم/یه ماشین خریدم/ماشینی خریدم"]]},
{lvl:"A2",t:"Simple past",n:"Past stem (infinitive minus ‑an) + ending; 3rd singular has no ending: raft “he went”. Negative: naraftam.",d:[["I went","رفتم"],["we ate","خوردیم"],["they came","آمدند/اومدن"]]},
{lvl:"A2",t:"Present progressive",n:"dāshtan (present) + the present tense: dāram miravam “I am going”. It has no negative form; use the plain negative present.",d:[["I'm going","دارم می روم/دارم میرم"],["she is eating","دارد می خورد/داره میخوره"],["we are working","داریم کار می کنیم/داریم کار میکنیم"]]},
{lvl:"A2",t:"Future",n:"Formal: khāh‑ + ending + short past stem: khāham raft. In speech the present tense is used for the future.",d:[["I will go","خواهم رفت"],["they will come","خواهند آمد"],["we will see","خواهیم دید"]]},
{lvl:"A2",t:"Imperative",n:"be‑ + present stem (singular), + ‑id for plural/polite. Negative: na‑. be‑ often becomes bo‑ or bi‑: boro, biyā.",d:[["go!","برو"],["come!","بیا"],["don't go!","نرو"],["please sit (polite)","بنشینید/بشینید/لطفاً بنشینید"]]},
{lvl:"A2",t:"Comparative and superlative",n:"‑tar makes the comparative; ‑tarin the superlative, which comes before the noun: bozorgtarin shahr. “Than” is az. Irregular: khub → behtar.",d:[["bigger","بزرگتر"],["the biggest city","بزرگترین شهر"],["better than me","بهتر از من"]]},
{lvl:"A2",t:"Indefinite: yek and ‑i",n:"yek (spoken ye) before the noun or ‑i after it marks “a / some”; both together is common in speech.",d:[["a book","یک کتاب/کتابی/یه کتاب"],["a man came","مردی آمد/یک مرد آمد/یه مرد اومد"]]},
{lvl:"B1",t:"Past progressive",n:"mi‑ + past stem + ending: miraftam “I was going / used to go”. dāshtan in the past adds emphasis: dāshtam miraftam.",d:[["I was going","داشتم می رفتم/می رفتم"],["we used to live here","اینجا زندگی می کردیم/ما اینجا زندگی می کردیم"]]},
{lvl:"B1",t:"Present perfect",n:"Past participle (past stem + ‑e) + short “to be”: rafte‑am “I have gone”. 3rd singular: rafte ast, spoken rafte.",d:[["I have gone","رفته ام"],["she has eaten","خورده است/خورده"],["have you seen?","دیده ای/دیدی"]]},
{lvl:"B1",t:"Past perfect",n:"Past participle + past of budan: rafte budam “I had gone”.",d:[["I had gone","رفته بودم"],["they had come","آمده بودند/اومده بودن"]]},
{lvl:"B1",t:"Subjunctive",n:"be‑ + present stem + ending. Used after khāstan, bāyad, shāyad, tavānestan and many conjunctions: mikhāham beravam “I want to go”.",d:[["I want to go","می خواهم بروم/میخوام برم"],["I must read","باید بخوانم/باید بخونم"],["maybe he'll come","شاید بیاید/شاید بیاد"],["I can speak","می توانم صحبت کنم/میتونم حرف بزنم"]]},
{lvl:"B1",t:"Relative clauses",n:"The head noun takes ‑i, followed by ke: mardi ke āmad “the man who came”. There is no separate who/which/that.",d:[["the man who came","مردی که آمد/مردی که اومد"],["the book that I read","کتابی که خواندم/کتابی که خوندم"]]},
{lvl:"B1",t:"Real conditionals",n:"agar + subjunctive (or simple past) in the if‑clause, present or future in the main clause.",d:[["if you come, I'll go","اگر بیایی می روم/اگه بیای میرم/اگر بیایی، می روم"],["if it rains, we stay","اگر باران بیاید می مانیم/اگه بارون بیاد میمونیم"]]},
{lvl:"B2",t:"Past subjunctive",n:"Past participle + subjunctive of budan (bāsham, bāshi, bāshad…): shāyad rafte bāshad “he may have gone”.",d:[["he may have gone","شاید رفته باشد/شاید رفته باشه"],["I must have forgotten","باید فراموش کرده باشم/لابد فراموش کرده ام"]]},
{lvl:"B2",t:"Unreal conditionals",n:"agar + past progressive in both clauses for unreal present and past: agar midānestam, miāmadam. Past perfect sharpens the past: agar dide budam…",d:[["if I knew, I would come","اگر می دانستم می آمدم/اگه میدونستم میومدم"],["if I had money","اگر پول داشتم/اگه پول داشتم"]]},
{lvl:"B2",t:"Passive",n:"Past participle + shodan: neveshte shod “it was written”. Speech often prefers an impersonal 3rd plural active instead.",d:[["it was written","نوشته شد"],["the door was opened","در باز شد"],["it will be built","ساخته خواهد شد/ساخته می شود"]]},
{lvl:"B2",t:"Causatives",n:"Present stem + ‑ān‑ forms a causative verb: khandidan “laugh” → khandāndan “make laugh”. Many compound verbs swap shodan ↔ kardan instead.",d:[["to make laugh","خنداندن"],["to make run","دواندن"],["to make someone understand","فهماندن"]]},
{lvl:"B2",t:"Formal vs spoken",n:"Spoken Tehrani shortens stems (miravad → mire, miguyad → mige), ‑ān → ‑un (nān → nun), ast → ‑e, and rā → ‑o.",d:[["he says (spoken)","میگه/می گه"],["he goes (spoken)","میره/می ره"],["bread (spoken)","نون"]]}
],
norm:function(s){
  return s.normalize("NFC").replace(/[يى]/g,"ی").replace(/ك/g,"ک").replace(/[ۀة]/g,"ه").replace(/[أإ]/g,"ا")
   .replace(/[\u064B-\u065F\u0670\u0640]/g,"").replace(/[\s\u200c\u200d\u00a0.,،؛;:!?؟«»"'()\-]/g,"").toLowerCase();
},
