"never":["never","pre","never"],"already; previously":["already","pre","past"],"recently":["recently","pre","past"],"finally":["finally","pre","past"],"suddenly":["suddenly","pre","past"],
"definitely":["will definitely","modal","fut"],"probably":["will probably","modal","fut"],"maybe":["maybe","maybe","subj"],"perhaps":["perhaps","maybe","subj"],
"also; too":["too","also","pres"],"today":["today","end","pres"],"tomorrow":["tomorrow","end","fut"],"yesterday":["yesterday","end","past"],"now":["now","end","prog"],
"tonight":["tonight","end","fut"],"this year":["this year","end","pres"],"last year":["last year","end","past"],"day after tomorrow":["the day after tomorrow","end","fut"],
"day before yesterday":["the day before yesterday","end","past"],"later":["later","end","fut"],"soon":["soon","end","fut"],"immediately":["immediately","end","fut"],
"early":["early","end","pres"],"late":["late","end","past"],"together":["together","end","together"],"alone":["alone","end","pres"],"again":["again","end","pres"],
